pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(msg) = decode_v2_hello(bytes) {
        return Ok(msg);
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

fn decode_v2_hello(bytes: &str) -> Option<Msg> {
    let bytes = bytes.trim();
    let prefix = r#"{"v":2,"hello":"#;
    let value = bytes.strip_prefix(prefix)?.strip_suffix('}')?;
    let (hello, used) = parse_json_string(value)?;
    if used != value.len() {
        return None;
    }
    Some(Msg::Hello(hello))
}

fn parse_json_string(value: &str) -> Option<(String, usize)> {
    let mut result = String::new();
    let mut chars = value.char_indices();
    if chars.next()?.1 != '"' {
        return None;
    }

    while let Some((index, ch)) = chars.next() {
        match ch {
            '"' => return Some((result, index + ch.len_utf8())),
            '\\' => {
                let (_, escaped) = chars.next()?;
                match escaped {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000c}'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'u' => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            let (_, digit) = chars.next()?;
                            code = code.checked_mul(16)?.checked_add(digit.to_digit(16)?)?;
                        }
                        result.push(char::from_u32(code)?);
                    }
                    _ => return None,
                }
            }
            ch if ch < '\u{0020}' => return None,
            _ => result.push(ch),
        }
    }
    None
}

fn encode_json_string(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len() + 2);
    encoded.push('"');
    for ch in value.chars() {
        match ch {
            '"' => encoded.push_str("\\\""),
            '\\' => encoded.push_str("\\\\"),
            '\u{0008}' => encoded.push_str("\\b"),
            '\u{000c}' => encoded.push_str("\\f"),
            '\n' => encoded.push_str("\\n"),
            '\r' => encoded.push_str("\\r"),
            '\t' => encoded.push_str("\\t"),
            ch if ch < '\u{0020}' => encoded.push_str(&format!("\\u{:04x}", ch as u32)),
            _ => encoded.push(ch),
        }
    }
    encoded.push('"');
    encoded
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"hello":{}}}"#, encode_json_string(value)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn roundtrip_ping() -> Msg {
        decode(&encode(&Msg::Ping)).unwrap()
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(roundtrip_ping(), Msg::Ping));
    }

    #[test]
    fn hello_uses_v2_envelope() {
        assert_eq!(encode(&Msg::Hello("world".into())), r#"{"v":2,"hello":"world"}"#);
    }

    #[test]
    fn hello_encode_roundtrip() {
        let value = "hello \"world\"\\line\n";
        assert!(matches!(decode(&encode(&Msg::Hello(value.into()))), Ok(Msg::Hello(decoded)) if decoded == value));
    }
}

