 27 | fn parse_json_string(value: &str) -> Option<(String, usize)> {
 28 |     let mut result = String::new();
 29 |     let mut chars = value.char_indices();
 30 |     if chars.next()?.1 != '"' {
 31 |         return None;
 32 |     }
 33 | 
 34 |     while let Some((index, ch)) = chars.next() {
 35 |         match ch {
 36 |             '"' => return Some((result, index + ch.len_utf8())),
 37 |             '\\' => {
 38 |                 let (_, escaped) = chars.next()?;
 39 |                 match escaped {
