 43 |                     'b' => result.push('\u{0008}'),
 44 |                     'f' => result.push('\u{000c}'),
 45 |                     'n' => result.push('\n'),
 46 |                     'r' => result.push('\r'),
 47 |                     't' => result.push('\t'),
 48 |                     'u' => {
 49 |                         let mut code = 0u32;
 50 |                         for _ in 0..4 {
 51 |                             let (_, digit) = chars.next()?;
 52 |                             code = code.checked_mul(16)?.checked_add(digit.to_digit(16)?)?;
